        """Simple mismatch at ends."""
        assert smallest_change([1, 2, 3, 5, 4, 7, 9, 6]) == 4

    def test_single_element(self):
        """Single element is always a palindrome."""
        assert smallest_change([5]) == 0

    def test_empty_array(self):
        """Empty array is a palindrome."""
        assert smallest_change([]) == 0

    def test_two_elements_match(self):
        """Two identical elements."""
        assert smallest_change([7, 7]) == 0

    def test_two_elements_mismatch(self):
        """Two different elements need 1 change."""
        assert smallest_change([3, 5]) == 1

    def test_three_elements_middle_mismatch(self):
        """Middle element doesn't affect palindrome status."""
        assert smallest_change([1, 9, 1]) == 0

